        <div class="source text" style="font-size: px; line-height: px;">
            <ol class="text"><li class="li1"><div class="de1"># how to run it? Open notepad, paste this script, save as a &quot;.py&quot;, then run it</div></li><li class="li1"><div class="de1"># how to install python? https://www.python.org/downloads/</div></li><li class="li1"><div class="de1"># pip install opencv-python numpy mss fastapi uvicorn</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">import sys</div></li><li class="li1"><div class="de1">import subprocess</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1"># List of required packages mapped to their import names if different</div></li><li class="li1"><div class="de1">REQUIRED_PACKAGES = {</div></li><li class="li1"><div class="de1">    &quot;opencv-python&quot;: &quot;cv2&quot;,</div></li><li class="li1"><div class="de1">    &quot;numpy&quot;: &quot;numpy&quot;,</div></li><li class="li1"><div class="de1">    &quot;mss&quot;: &quot;mss&quot;,</div></li><li class="li1"><div class="de1">    &quot;fastapi&quot;: &quot;fastapi&quot;,</div></li><li class="li1"><div class="de1">    &quot;uvicorn&quot;: &quot;uvicorn&quot;</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">def check_and_install_dependencies():</div></li><li class="li1"><div class="de1">    missing_packages = []</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    for pkg_name, import_name in REQUIRED_PACKAGES.items():</div></li><li class="li1"><div class="de1">        try:</div></li><li class="li1"><div class="de1">            __import__(import_name)</div></li><li class="li1"><div class="de1">        except ImportError:</div></li><li class="li1"><div class="de1">            missing_packages.append(pkg_name)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    if missing_packages:</div></li><li class="li1"><div class="de1">        print(f&quot;[Setup] Missing dependencies detected: {&#039;, &#039;.join(missing_packages)}&quot;)</div></li><li class="li1"><div class="de1">        print(&quot;[Setup] Installing required packages...&quot;)</div></li><li class="li1"><div class="de1">        try:</div></li><li class="li1"><div class="de1">            subprocess.check_call([sys.executable, &quot;-m&quot;, &quot;pip&quot;, &quot;install&quot;, *missing_packages])</div></li><li class="li1"><div class="de1">            print(&quot;[Setup] All dependencies installed successfully!\n&quot;)</div></li><li class="li1"><div class="de1">        except Exception as err:</div></li><li class="li1"><div class="de1">            print(f&quot;[Error] Failed to install dependencies: {err}&quot;)</div></li><li class="li1"><div class="de1">            sys.exit(1)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1"># run the auto check thing</div></li><li class="li1"><div class="de1">check_and_install_dependencies()</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">import base64</div></li><li class="li1"><div class="de1">import threading</div></li><li class="li1"><div class="de1">import time</div></li><li class="li1"><div class="de1">import os</div></li><li class="li1"><div class="de1">from contextlib import asynccontextmanager</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">import cv2</div></li><li class="li1"><div class="de1">import numpy as np</div></li><li class="li1"><div class="de1">import mss</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">from fastapi import FastAPI, Query</div></li><li class="li1"><div class="de1">from fastapi.responses import PlainTextResponse</div></li><li class="li1"><div class="de1">import uvicorn</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">NUM_CORES = os.cpu_count() or 4</div></li><li class="li1"><div class="de1">cv2.setNumThreads(NUM_CORES)</div></li><li class="li1"><div class="de1">cv2.setUseOptimized(True)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">MONITOR_INDEX = 1  # Primary monitor</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">latest_frame = None</div></li><li class="li1"><div class="de1">frame_lock = threading.Lock()</div></li><li class="li1"><div class="de1">capture_running = True</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">def capture_loop():</div></li><li class="li1"><div class="de1">    global latest_frame</div></li><li class="li1"><div class="de1">    print(f&quot;[Server] capture active across {NUM_CORES} CPU cores.&quot;)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    # Fixed: mss.mss() is a function factory, not a class named MSS</div></li><li class="li1"><div class="de1">    with mss.mss() as sct:</div></li><li class="li1"><div class="de1">        monitor = sct.monitors[MONITOR_INDEX]</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">        while capture_running:</div></li><li class="li1"><div class="de1">            try:</div></li><li class="li1"><div class="de1">                screenshot = sct.grab(monitor)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                frame = np.frombuffer(screenshot.rgb, dtype=np.uint8).reshape(</div></li><li class="li1"><div class="de1">                    (screenshot.height, screenshot.width, 3)</div></li><li class="li1"><div class="de1">                )</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                with frame_lock:</div></li><li class="li1"><div class="de1">                    latest_frame = frame</div></li><li class="li1"><div class="de1">            except Exception as exc:</div></li><li class="li1"><div class="de1">                print(f&quot;[Server] Capture error: {exc}&quot;)</div></li><li class="li1"><div class="de1">                time.sleep(0.001)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">capture_thread = threading.Thread(target=capture_loop, daemon=True)</div></li><li class="li1"><div class="de1">capture_thread.start()</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1"># Fixed deprecation warning: using FastAPI Lifespan instead of @app.on_event(&quot;startup&quot;)</div></li><li class="li1"><div class="de1">@asynccontextmanager</div></li><li class="li1"><div class="de1">async def lifespan(app: FastAPI):</div></li><li class="li1"><div class="de1">    print(&quot;[Server] Started!&quot;)</div></li><li class="li1"><div class="de1">    print(&quot;[Server] Success! Capturing screen&quot;)</div></li><li class="li1"><div class="de1">    yield</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">app = FastAPI(lifespan=lifespan)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">@app.get(&quot;/screen&quot;, response_class=PlainTextResponse)</div></li><li class="li1"><div class="de1">def get_screen(</div></li><li class="li1"><div class="de1">    w: int = Query(85, ge=1, le=640),</div></li><li class="li1"><div class="de1">    h: int = Query(48, ge=1, le=360),</div></li><li class="li1"><div class="de1">    channels: int = Query(3)</div></li><li class="li1"><div class="de1">):</div></li><li class="li1"><div class="de1">    with frame_lock:</div></li><li class="li1"><div class="de1">        if latest_frame is None:</div></li><li class="li1"><div class="de1">            return &quot;&quot;</div></li><li class="li1"><div class="de1">        frame = latest_frame</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    # Accelerated downscaling</div></li><li class="li1"><div class="de1">    resized = cv2.resize(frame, (w, h), interpolation=cv2.INTER_AREA)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    return base64.b64encode(resized.tobytes()).decode(&quot;ascii&quot;)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">if __name__ == &quot;__main__&quot;:</div></li><li class="li1"><div class="de1">    try:</div></li><li class="li1"><div class="de1">        uvicorn.run(</div></li><li class="li1"><div class="de1">            app, </div></li><li class="li1"><div class="de1">            host=&quot;127.0.0.1&quot;, </div></li><li class="li1"><div class="de1">            port=5000, </div></li><li class="li1"><div class="de1">            log_level=&quot;warning&quot;</div></li><li class="li1"><div class="de1">        )</div></li><li class="li1"><div class="de1">    except Exception as e:</div></li><li class="li1"><div class="de1">        print(f&quot;\n[Error] Server crashed: {e}&quot;)</div></li><li class="li1"><div class="de1">        input(&quot;Press Enter to exit...&quot;)</div></li></ol>        </div>
    </div>

    

        
    
                
